    # --- two-point block descent: joint relocation of point pairs drawn
    # from the active (minimum-area) triples.  Single-point or label-swap
    # moves cannot realize improvements that require two vertices to move
    # simultaneously in opposite directions, because each intermediate
    # single-point move is rejected by the accept-only-if-better guard.
    # For each active pair (p, q) the other 9 points are held fixed and a
    # deterministic coarse product grid (21x21 = 441 placements) of
    # interior barycentric coordinates is scanned in closed form against
    # the exact 165-triangle minimum.  The best grid placement is then
    # repolished (pair-only softmin SLSQP, then full-variable softmin
    # SLSQP) and accepted only if the exact minimum strictly improves and
    # validity holds.  Budget: at most 60 block iterations.
    if best_B is not None:
        grid = []
        for a in range(1, 8):
            for b in range(1, 8 - a):
                grid.append(np.array([a, b, 8 - a - b], dtype=float) / 8.0)
        grid = np.array(grid)  # 21 interior barycentric points, margin 1/8

        def repolish_pair(Bc, p, q, t=500.0):
            Bw = Bc.copy()

            def to_B(x):
                E = np.exp(x.reshape(2, 3)
                           - x.reshape(2, 3).max(axis=1, keepdims=True))
                return E / E.sum(axis=1, keepdims=True)

            z0 = np.log(np.clip(Bw[[p, q]], 1e-9, None)).ravel()

            def obj(x):
                Bt = Bw.copy()
                Bt[[p, q]] = to_B(x)
                return -softmin(all_areas(Bt), t)

            try:
                res = minimize(obj, z0, method="SLSQP",
                               options={"maxiter": 150, "ftol": 1e-14})
                Bt = Bw.copy()
                Bt[[p, q]] = to_B(res.x)
                return Bt
            except Exception:
                return Bc

